#include <vector>

class Solution {
public:
    long long countSinglePeakSubarrays(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<int> peaks;
        for (int i = 1; i < n - 1; ++i) {
            if (nums[i] > nums[i - 1] && nums[i] > nums[i + 1]) {
                peaks.push_back(i);
            }
        }
        if (peaks.empty()) return 0;
        long long ans = 0;
        int m = peaks.size();
        for (int k = 0; k < m; ++k) {
            int cur = peaks[k];
            int left_bound = (k > 0) ? (peaks[k - 1] + 1) : 0;
            int right_bound = (k < m - 1) ? (peaks[k + 1] - 1) : n - 1;
            long long left_choices = cur - left_bound + 1;
            long long right_choices = right_bound - cur + 1;
            ans += left_choices * right_choices;
        }
        return ans;
    }
};

