        for (int k = 0; k < m; k++) {
            int cur = peaks.get(k);
            int leftBound = (k > 0) ? (peaks.get(k - 1) + 1) : 0;
            int rightBound = (k < m - 1) ? (peaks.get(k + 1) - 1) : n - 1;
            long leftChoices = cur - leftBound + 1;
            long rightChoices = rightBound - cur + 1;
            ans += leftChoices * rightChoices;
        }
        return ans;
    }
}

